experiments.forEach(e=>{e.subject="Chemistry";e.difficulty="Explore";});
experiments.push(...physicsExperiments);
export function simulate(id,p,t){
 if(physicsExperiments.some(e=>e.id===id))return simulatePhysics(id,p,t);
 t=Math.max(0,Math.min(1,t));
 if(id==='titration'){let v=p.volume*t,delta=(.0025-p.concentration*v/1000)/(.025+v/1000),h=delta>=0?(delta+Math.sqrt(delta*delta+4e-14))/2:2e-14/(Math.sqrt(delta*delta+4e-14)-delta);let ph=-Math.log10(h);return {a:ph,b:v,pink:Math.max(0,Math.min(1,(ph-8.2)/1.8)),hint:ph<6?'The acid is still in excess. Keep an eye on the pH.':ph<8.2?'Near the equivalence point. Every drop matters.':'The base is now in excess. Notice the pink indicator.'};}
 if(id==='gas'){let n=Math.min(p.mass/100.086,.02*p.concentration/2),reaction=(1-Math.exp(-4*t))/(1-Math.exp(-4));return {a:n*24470*reaction,b:reaction*100,hint:'The final gas volume depends on the limiting reactant.'};}
 if(id==='electrolysis'){let mol=p.current*p.duration*t/96485;return {a:mol/2*24470,b:mol/4*24470,hint:'Hydrogen collects at twice the volume of oxygen.'};}
 if(id==='precipitation')return {a:Math.min(p.silver,p.salt)*.01*143.32*1000*t,b:t*100,hint:t>0?'The white cloud is solid silver chloride.':'Both solutions are clear before they are combined.'};
 if(id==='heating'){let q=p.power*120*t;return {a:Math.min(100,20+q/(p.mass*4.184)),b:q/1000,vapor:Math.max(0,Math.min(.95,(q-p.mass*4.184*80)/(2257*p.mass))),hint:q>p.mass*4.184*80?'Boiling: added energy now changes liquid to vapor.':'Temperature rises as the water absorbs energy.'};}
 let d=(p.temperature+273.15)/298.15*Math.exp((p.temperature-25)/55);return {a:Math.sqrt(d*t),b:120*t,spread:Math.min(1,Math.sqrt(d*t)),hint:'Color spreads from a region of high concentration to low concentration.'};
}
